import { act } from 'react';
import { describe, expect, it, vi } from 'vitest';

import { EditorView } from '@codemirror/view';

import { mountDom, unmountDom } from '~/components/__tests__/helpers/dom';
import press, { findButton } from '~/components/__tests__/helpers/press';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

import NewMessageJsonInput from '../NewMessageJsonInput';

function mount() {
  return mountDom(<NewMessageJsonInput setMessage={() => {}} />);
}

async function type(el: HTMLElement, json: string) {
  const view = EditorView.findFromDOM(el.querySelector('.cm-editor') as HTMLElement)!;
  await act(async () => {
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: json } });
  });
}

const CONFLICT_JSON = JSON.stringify({
  content: 'hello', flags: 32768, components: [{ type: 10, content: 'x' }],
});

describe('NewMessageJsonInput — conflict resting state', () => {
  it('a conflicting edit rests on the dismissed-choice notice with a Resolve link, not the choice buttons', async () => {
    const el = mount();
    await type(el, CONFLICT_JSON);

    expect(el.textContent).toContain('nothing was created');
    expect(el.textContent).not.toContain('Save as Classic');
    expect(el.textContent).not.toContain('Save as Components V2');
    findButton(el, 'Resolve');
    unmountDom();
  });

  it('the Resolve link reopens the choice buttons (pendingChoice stays reachable)', async () => {
    const el = mount();
    await type(el, CONFLICT_JSON);

    press(findButton(el, 'Resolve'));

    expect(el.textContent).toContain('Save as Classic');
    expect(el.textContent).toContain('Save as Components V2');
    expect(el.textContent).not.toContain('nothing was created');
    unmountDom();
  });
});

