import { act } from 'react';
import {
  describe, it, expect, vi, afterEach,
} from 'vitest';

import { EditorView } from '@codemirror/view';

import { unmountDom } from '~/components/__tests__/helpers/dom';
import press, { findButton } from '~/components/__tests__/helpers/press';
import { mountInMessageProvider } from '~/providers/MessageProvider/__tests__/helpers/mountMessageProvider';

vi.mock('~/env.mjs', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).ENV_MOCK);
vi.mock('next/navigation', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).navigationMock());
vi.mock('next-auth/react', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).AUTH_MOCK);
vi.mock('~/utils/api', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).buildApiMock());
vi.mock('~/providers/GuildProvider', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).GUILD_PROVIDER_MOCK);
vi.mock('~/providers/WebhookProvider', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).WEBHOOK_PROVIDER_MOCK);
vi.mock('~/providers/ConfirmationProvider', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).CONFIRMATION_PROVIDER_MOCK);

import JsonModalBody from '../JsonModalBody';

afterEach(unmountDom);

function mount(onClose: () => void) {
  return mountInMessageProvider(
    <JsonModalBody onClose={onClose} setAllowMenuClose={() => {}} />,
  );
}

async function type(el: HTMLElement, json: string) {
  const view = EditorView.findFromDOM(el.querySelector('.cm-editor') as HTMLElement)!;
  await act(async () => {
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: json } });
  });
}

function docText(el: HTMLElement): string {
  const view = EditorView.findFromDOM(el.querySelector('.cm-editor') as HTMLElement)!;
  return view.state.doc.toString();
}

const CONFLICT_JSON = JSON.stringify({
  content: 'hello', flags: 32768, components: [{ type: 10, content: 'x' }],
});

async function reachChoiceButtons(el: HTMLElement) {
  await type(el, CONFLICT_JSON);
  // The conflict rests on the dismissed-choice notice, not the choice buttons — reach them via
  // the Resolve link, same as a real user would.
  press(findButton(el, 'Resolve'));
}

describe('JsonModalBody — choosing Classic/V2 rewrites the editor', () => {
  it('choosing Classic rewrites the doc to the classic disposition, does not close the modal', async () => {
    const onClose = vi.fn();
    const el = mount(onClose);
    await reachChoiceButtons(el);

    press(findButton(el, 'Save as Classic'));

    expect(onClose).not.toHaveBeenCalled();
    expect(el.textContent).not.toContain('Save as Classic');
    expect(el.textContent).not.toContain('Save as Components V2');
    expect(el.textContent).toContain('Load');

    const parsed = JSON.parse(docText(el)) as { components?: unknown[], flags?: number };
    expect(parsed.components ?? []).toEqual([]);
    expect((parsed.flags ?? 0) & 32768).toBe(0);
  });

  it('choosing Components V2 rewrites the doc to the v2 disposition, does not close the modal', async () => {
    const onClose = vi.fn();
    const el = mount(onClose);
    await reachChoiceButtons(el);

    press(findButton(el, 'Save as Components V2'));

    expect(onClose).not.toHaveBeenCalled();
    expect(el.textContent).not.toContain('Save as Classic');
    expect(el.textContent).not.toContain('Save as Components V2');
    expect(el.textContent).toContain('Load');

    const parsed = JSON.parse(docText(el)) as { content?: string, flags?: number };
    expect(parsed.content ?? '').toBe('');
    expect((parsed.flags ?? 0) & 32768).toBe(32768);
  });

  it('choosing an option clears both choice states — the dismissed-choice Resolve notice does not return', async () => {
    const el = mount(() => {});
    await reachChoiceButtons(el);

    press(findButton(el, 'Save as Classic'));

    expect(el.textContent).not.toContain('nothing was loaded');
    expect(el.textContent).not.toContain('Resolve');
  });
});

