import { act } from 'react';
import { toast } from 'react-toastify';
import {
  describe, expect, it, vi, afterEach,
} from 'vitest';

import { mountDom, unmountDom } from '~/components/__tests__/helpers/dom';

vi.mock('~/env.mjs', async () => (await import('./helpers/messageProviderDeps')).ENV_MOCK);
vi.mock('next/navigation', async () => (await import('./helpers/messageProviderDeps')).navigationMock());
vi.mock('next-auth/react', async () => (await import('./helpers/messageProviderDeps')).AUTH_MOCK);
vi.mock('~/providers/GuildProvider', async () => (await import('./helpers/messageProviderDeps')).GUILD_PROVIDER_MOCK);
vi.mock('~/providers/WebhookProvider', async () => (await import('./helpers/messageProviderDeps')).WEBHOOK_PROVIDER_MOCK);
vi.mock('~/providers/ConfirmationProvider', async () => (await import('./helpers/messageProviderDeps')).CONFIRMATION_PROVIDER_MOCK);
vi.mock('~/utils/api', async () => {
  const { buildApiMock } = await import('./helpers/messageProviderDeps');
  let capturedOnMutate: (() => void) | undefined;
  const mock = buildApiMock({
    queryErrors: { 'message.getFromCode': { message: 'boom' } },
    onMutation: {
      'message.upsert': (opts) => { capturedOnMutate = opts.onMutate as (() => void) | undefined; capturedOnMutate?.(); },
    },
  });
  return mock;
});

import MessageProvider, { useMessage } from '~/providers/MessageProvider';

afterEach(unmountDom);

let ctx: ReturnType<typeof useMessage> | null = null;
function Probe() {
  ctx = useMessage();
  return null;
}

describe('MessageProvider — transient notices still use toast (not a blanket removal)', () => {
  it('a code-fetch query error toasts (toast.error)', () => {
    const spy = vi.spyOn(toast, 'error').mockImplementation(() => 'id');
    act(() => { mountDom(<MessageProvider><Probe /></MessageProvider>); });

    expect(spy).toHaveBeenCalledWith('boom');
    spy.mockRestore();
