import { describe, it, expect, vi } from 'vitest';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

import {
  readFileSync, mkdtempSync, rmSync, writeFileSync,
} from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';

import {
  emptyReport, accumulate, formatReport, persistReport, emit, reportPath,
  resolveTargetHost, assertConfirmedTarget, hasConnectionOverrideParams, assertNoHostOverride,
} from '~/scripts/backfillValid';

function fakeDatabase(countResult: Promise<{ count: number }>) {
  return {
    selectFrom: () => ({
      select: () => ({ executeTakeFirstOrThrow: () => countResult }),
    }),
    fn: { countAll: () => ({ as: () => 'count' }) },
  } as unknown as Parameters<typeof emit>[1];
}

describe('emptyReport / accumulate — every breakout category carries row ids', () => {
  it('starts with rowsClassifiedThisRun: 0, not `total`', () => {
    const report = emptyReport();
    expect(report.rowsClassifiedThisRun).toBe(0);
    expect('total' in report).toBe(false);
  });

  it('flagStructureDisagreement carries rowIds alongside count', () => {
    const report = emptyReport();
    accumulate(report, 'row-1', {
      valid: false,
      firstFailingCheck: 'x',
      flagStructureDisagreement: true,
      whitespaceContent: false,
      evaluationFailure: false,
    });
    expect(report.flagStructureDisagreement).toEqual({ count: 1, rowIds: ['row-1'] });
  });

  it('flagStructureDisagreementValidTrue is a distinct, id-carrying category (the invisible sub-class)', () => {
    const report = emptyReport();
    accumulate(report, 'row-2', {
      valid: true,
      flagStructureDisagreement: true,
      whitespaceContent: false,
      evaluationFailure: false,
    });
    expect(report.flagStructureDisagreementValidTrue).toEqual({ count: 1, rowIds: ['row-2'] });
    expect(report.trueCount).toBe(1);
    expect(report.falseCount).toBe(0);
  });

  it('a flag/structure disagreement on an invalid row does not populate the validTrue category', () => {
    const report = emptyReport();
    accumulate(report, 'row-3', {
      valid: false,
      firstFailingCheck: 'x',
      flagStructureDisagreement: true,
      whitespaceContent: false,
      evaluationFailure: false,
    });
    expect(report.flagStructureDisagreementValidTrue).toEqual({ count: 0, rowIds: [] });
  });
});

describe('formatReport — coverage-labelled, so a partial run cannot read as whole-table', () => {
  it('includes the table-wide count alongside the accumulated count under distinct names', () => {
    const report = emptyReport();
    accumulate(report, 'r1', {
      valid: true,
      flagStructureDisagreement: false,
      whitespaceContent: false,
      evaluationFailure: false,
    });
    const content = formatReport(report, { tableWideRowCount: 500 });
    const parsed = JSON.parse(content);
    expect(parsed.rowsClassifiedThisRun).toBe(1);
    expect(parsed.tableWideRowCount).toBe(500);
  });

  it('marks an interrupted run explicitly', () => {
    const content = formatReport(emptyReport(), { tableWideRowCount: 500, interrupted: true });
    expect(JSON.parse(content).interrupted).toBe(true);
  });

  it('carries the run\'s provenance stamps in the persisted body, so a future refactor cannot silently drop them', () => {
    const content = formatReport(emptyReport(), {
      tableWideRowCount: 0, runId: 'run-1', startedAt: 'start-1', endedAt: 'end-1',
    });
    const parsed = JSON.parse(content);
    expect(parsed.runId).toBe('run-1');
    expect(parsed.startedAt).toBe('start-1');
    expect(parsed.endedAt).toBe('end-1');
  });
});

describe('persistReport — writes the report to disk, not only stdout (H2)', () => {
  it('creates the destination directory and writes the content', () => {
    const dir = mkdtempSync(join(tmpdir(), '012-backfill-report-'));
    const target = join(dir, 'nested', 'backfill-report.md');
    try {
      persistReport('{"ok":true}', target);
      expect(readFileSync(target, 'utf8')).toContain('"ok":true');
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it('refuses to overwrite an existing report, so a rehearsal cannot silently replace the gate\'s evidence', () => {
    const dir = mkdtempSync(join(tmpdir(), '012-backfill-report-'));
    const target = join(dir, 'backfill-report.md');
    try {
      persistReport('{"run":1}', target);
      expect(() => persistReport('{"run":2}', target)).toThrow(/EEXIST/);
      expect(readFileSync(target, 'utf8')).toContain('"run":1');
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

describe('reportPath — one filename per run, so overwrite-refusal does not block a legitimate retry', () => {
  it('embeds the given run id in the filename', () => {
    expect(reportPath('run-abc123')).toMatch(/backfill-report-run-abc123\.md$/);
  });

  it('two different run ids produce two different paths', () => {
    expect(reportPath('run-a')).not.toBe(reportPath('run-b'));
  });

  it('honours an explicit report directory override', () => {
    expect(reportPath('run-x', '/tmp/some-other-dir')).toBe('/tmp/some-other-dir/backfill-report-run-x.md');
  });
});

describe('resolveTargetHost — the host the backfill would actually connect to', () => {
  it('extracts host:port from a DATABASE_URL', () => {
    expect(resolveTargetHost('postgresql://user:pw@viaduct.proxy.rlwy.net:12394/railway')).toBe('viaduct.proxy.rlwy.net:12394');
  });

  it('defaults the port to 5432 when the URL omits one', () => {
    expect(resolveTargetHost('postgresql://user:pw@example.com/db')).toBe('example.com:5432');
  });

  it('returns a sentinel for an unset DATABASE_URL', () => {
    expect(resolveTargetHost(undefined)).toBe('(unset)');
  });

  it('returns a sentinel for an unparseable DATABASE_URL', () => {
    expect(resolveTargetHost('not-a-url')).toBe('(unparseable)');
  });
});

describe('assertConfirmedTarget — refuses to run against an unacknowledged target', () => {
  it('throws when BACKFILL_CONFIRM is unset', () => {
    expect(() => assertConfirmedTarget('viaduct.proxy.rlwy.net:12394', undefined))
      .toThrow(/viaduct\.proxy\.rlwy\.net:12394/);
  });

  it('throws when BACKFILL_CONFIRM names a different host than DATABASE_URL resolves to', () => {
    expect(() => assertConfirmedTarget('viaduct.proxy.rlwy.net:12394', '127.0.0.1:1'))
      .toThrow(/viaduct\.proxy\.rlwy\.net:12394/);
  });

  it('does not throw when BACKFILL_CONFIRM matches the resolved host exactly', () => {
    expect(() => assertConfirmedTarget('127.0.0.1:1', '127.0.0.1:1')).not.toThrow();
  });

  it('refuses a sentinel value as a confirmation, even if it happened to equal the resolved host', () => {
    expect(() => assertConfirmedTarget('(unset)', '(unset)')).toThrow(/sentinel/);
    expect(() => assertConfirmedTarget('(unparseable)', '(unparseable)')).toThrow(/sentinel/);
  });
});

describe('hasConnectionOverrideParams — the guard\'s parser and pg\'s parser can disagree on a query-string override', () => {
  it('is false for a plain DATABASE_URL with no query string', () => {
    expect(hasConnectionOverrideParams('postgresql://user:pw@viaduct.proxy.rlwy.net:12394/railway')).toBe(false);
  });

  it('is true when the URL carries a "host" query parameter', () => {
    expect(hasConnectionOverrideParams('postgresql://user:pw@decoy.invalid:1/db?host=127.0.0.1')).toBe(true);
  });

  it('is true when the URL carries a "port" query parameter', () => {
    expect(hasConnectionOverrideParams('postgresql://user:pw@decoy.invalid:1/db?port=1')).toBe(true);
  });

  it('is false for an unset or unparseable DATABASE_URL', () => {
    expect(hasConnectionOverrideParams(undefined)).toBe(false);
    expect(hasConnectionOverrideParams('not-a-url')).toBe(false);
  });
});

describe('assertNoHostOverride — refuses outright when the guard cannot trust its own parsed host', () => {
  it('throws when the URL carries a host override, regardless of confirmation', () => {
    expect(() => assertNoHostOverride('postgresql://user:pw@decoy.invalid:1/db?host=127.0.0.1'))
      .toThrow(/host.*query parameter|query parameter.*host/i);
  });

  it('throws when the URL carries a port override', () => {
    expect(() => assertNoHostOverride('postgresql://user:pw@decoy.invalid:1/db?port=1'))
      .toThrow(/port/i);
  });

  it('does not throw for a plain DATABASE_URL', () => {
    expect(() => assertNoHostOverride('postgresql://user:pw@viaduct.proxy.rlwy.net:12394/railway')).not.toThrow();
  });

  it('does not throw for an unset DATABASE_URL (a separate guard, assertConfirmedTarget, owns that case)', () => {
    expect(() => assertNoHostOverride(undefined)).not.toThrow();
  });
});

describe('emit — H3: symmetric guard, stdout before disk, a persist failure does not swallow the run', () => {
  it('guards a failing table-wide count the same way on every call, not only on one path', async () => {
    const dir = mkdtempSync(join(tmpdir(), '012-backfill-emit-'));
    const target = join(dir, 'backfill-report.md');
    const writeSpy = vi.spyOn(process.stdout, 'write').mockImplementation(() => true);
    try {
      await emit(emptyReport(), fakeDatabase(Promise.reject(new Error('down'))), target, {});
      const written = JSON.parse(readFileSync(target, 'utf8'));
      expect(written.tableWideRowCount).toBe(-1);
    } finally {
      writeSpy.mockRestore();
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it('writes stdout before attempting to persist, so a persist failure does not also lose stdout', async () => {
    const dir = mkdtempSync(join(tmpdir(), '012-backfill-emit-'));
    const notADirectory = join(dir, 'file');
    writeFileSync(notADirectory, 'not a directory');
    const target = join(notADirectory, 'nested', 'backfill-report.md');
    const writeSpy = vi.spyOn(process.stdout, 'write').mockImplementation(() => true);
    const errorSpy = vi.spyOn(console, 'error').mockImplementation(() => undefined);
    try {
      await expect(
        emit(emptyReport(), fakeDatabase(Promise.resolve({ count: 7 })), target, {}),
      ).resolves.toBeUndefined();
      expect(writeSpy).toHaveBeenCalledTimes(1);
      expect(String(writeSpy.mock.calls[0][0])).toContain('"tableWideRowCount": 7');
      expect(errorSpy).toHaveBeenCalledTimes(1);
    } finally {
      writeSpy.mockRestore();
      errorSpy.mockRestore();
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

