const database = new Kysely<DatabaseSchema>({
  dialect: {
    createAdapter: () => new PostgresAdapter(),
    createDriver: () => new DummyDriver(),
    createIntrospector: (db) => new PostgresIntrospector(db),
    createQueryCompiler: () => new PostgresQueryCompiler(),
  },
});

function values(overrides: Record<string, unknown> = {}) {
  return {
    updatedAt: new Date('2026-08-23T00:00:00Z'),
    name: 'test',
    data: { content: 'Hi', username: 'U', embeds: [], components: [] },
    fk_users_id: 'u1',
    fk_guilds_id: null,
    previewImageNonce: 'n',
    valid: true,
    ...overrides,
  };
}

describe('the conflict branch names `valid` explicitly, both directions', () => {
  it('insert column list carries `valid`', () => {
    const compiled = buildUpsertMessageQuery(database, values()).compile();
    expect(compiled.sql).toMatch(/"valid"/);
  });

  it('`on conflict … do update set` also carries `valid` — the enumerated trap', () => {
    const compiled = buildUpsertMessageQuery(database, values()).compile();
    const conflictClause = compiled.sql.slice(compiled.sql.indexOf('on conflict'));
    expect(conflictClause).toMatch(/"valid"\s*=/);
  });

  it('an update whose verdict is unchanged still writes `valid` (no conditional omission)', () => {
    const compiledTrue = buildUpsertMessageQuery(database, values({ valid: true })).compile();
    const compiledFalse = buildUpsertMessageQuery(database, values({ valid: false })).compile();
    const trueConflict = compiledTrue.sql.slice(compiledTrue.sql.indexOf('on conflict'));
    const falseConflict = compiledFalse.sql.slice(compiledFalse.sql.indexOf('on conflict'));
    expect(trueConflict).toMatch(/"valid"\s*=/);
    expect(falseConflict).toMatch(/"valid"\s*=/);
    expect(compiledTrue.parameters).toContain(true);
    expect(compiledFalse.parameters).toContain(false);
  });
});

describe('buildMessageValues computes `valid` from the predicate, never from the caller', () => {
  it('a sendable payload computes valid: true', () => {
