import {
  describe, it, expect, vi,
} from 'vitest';

import {
  hasV2Components,
  enforceImportMutualExclusivity,
} from '~/utils';
import { validateContentRequirements } from '~/utils/limits';

// Mock env.mjs to prevent environment variable validation at import time
vi.mock('~/env.mjs', () => ({
  env: {
    NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test',
  },
}));

// Mock SVG components imported by utils/index.ts
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import {
  makeLinkButton, makeActionRow, makeTextDisplay, makeThumbnail, makeSection,
  makeMediaGallery, makeFile, makeSeparator, makeContainer,
} from '~/utils/__tests__/helpers/components';

// ============================================================
// Tests: enforceImportMutualExclusivity
// ============================================================

describe('enforceImportMutualExclusivity', () => {
  describe('V2 data detected → strips content/embeds', () => {
    it('strips content when V2 components present', () => {
      const input = {
        content: 'should be removed',
        components: [makeTextDisplay()],
      };
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(data.content).toBeUndefined();
      expect(detectedMode).toBe('v2');
    });

    it('strips embeds when V2 components present', () => {
      const input = {
        embeds: [{ title: 'should be removed' }],
        components: [makeContainer()],
      };
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(data.embeds).toBeUndefined();
      expect(detectedMode).toBe('v2');
    });

    it('strips both content and embeds when V2 components present', () => {
      const input = {
        content: 'text',
        embeds: [{ title: 'embed' }],
        components: [makeSection(), makeTextDisplay()],
      };
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(data.content).toBeUndefined();
      expect(data.embeds).toBeUndefined();
      expect(detectedMode).toBe('v2');
    });

    it('preserves V2 components when stripping classic data', () => {
      const input = {
        content: 'strip me',
        components: [makeTextDisplay('keep me'), makeSeparator()],
      };
      const { data } = enforceImportMutualExclusivity(input);
      expect(data.components).toHaveLength(2);
      expect((data.components![0] as { content: string }).content).toBe('keep me');
    });

    it('detects V2 mode for all V2 component types', () => {
      const v2Types = [
        makeSection(),
        makeTextDisplay(),
        makeThumbnail(),
        makeMediaGallery(),
        makeFile(),
        makeSeparator(),
        makeContainer(),
      ];
      for (const component of v2Types) {
        const { detectedMode } = enforceImportMutualExclusivity({
          components: [component],
        });
        expect(detectedMode).toBe('v2');
      }
    });
  });

  describe('classic data detected → strips V2 components', () => {
    it('strips V2 components when only classic data present (no V2)', () => {
      const input = {
        content: 'keep',
        embeds: [{ title: 'keep too' }],
        components: [makeActionRow()],
      };
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(data.content).toBe('keep');
      expect(data.embeds).toHaveLength(1);
      expect(data.components).toHaveLength(1); // ActionRow is not V2
      expect(detectedMode).toBe('classic');
    });

    it('preserves legacy ActionRows in classic mode', () => {
      const input = {
        content: 'hello',
        components: [makeActionRow([makeLinkButton()])],
      };
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(data.components).toHaveLength(1);
      expect((data.components![0] as { type: number }).type).toBe(1);
      expect(detectedMode).toBe('classic');
    });

    it('filters out V2 types from mixed components when V2 is not dominant', () => {
      // When NO V2 types exist, it's classic mode — this tests the else branch.
      // With only ActionRow (type 1), the filter should pass it through.
      const input = {
        content: 'hello',
        components: [makeActionRow()],
      };
      const { data } = enforceImportMutualExclusivity(input);
      expect(data.components).toHaveLength(1);
    });
  });

  describe('edge cases', () => {
    it('handles empty components array', () => {
      const input = {
        content: 'hello',
        components: [] as { type: number }[],
      };
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(data.content).toBe('hello');
      expect(data.components).toHaveLength(0);
      expect(detectedMode).toBe('classic');
    });

    it('handles undefined components', () => {
      const input = {
        content: 'hello',
        embeds: [{ title: 'Test' }],
      };
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(data.content).toBe('hello');
      expect(data.embeds).toHaveLength(1);
      expect(detectedMode).toBe('classic');
    });

    it('handles data with no fields at all', () => {
      const input = {};
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(detectedMode).toBe('classic');
      expect(data).toEqual({});
    });

    it('does not mutate the input object', () => {
      const input = {
        content: 'hello',
        embeds: [{ title: 'Test' }],
        components: [makeTextDisplay()],
      };
      const inputStr = JSON.stringify(input);
      enforceImportMutualExclusivity(input);
      expect(JSON.stringify(input)).toBe(inputStr);
    });

    it('returns a shallow copy (not the same reference)', () => {
      const input = { content: 'hello', components: [makeActionRow()] };
      const { data } = enforceImportMutualExclusivity(input);
      expect(data).not.toBe(input);
    });

    it('V2 mode takes precedence: V2 + ActionRow mixed → V2 mode', () => {
      const input = {
        content: 'strip me',
        embeds: [{ title: 'strip me too' }],
        components: [makeActionRow(), makeTextDisplay()],
      };
      const { data, detectedMode } = enforceImportMutualExclusivity(input);
      expect(detectedMode).toBe('v2');
      expect(data.content).toBeUndefined();
      expect(data.embeds).toBeUndefined();
      // Both ActionRow and TextDisplay should be preserved
      expect(data.components).toHaveLength(2);
    });
  });
});

// ============================================================
// Tests: validateContentRequirements
// ============================================================

describe('validateContentRequirements', () => {
  describe('valid messages', () => {
    it('returns undefined for classic message with content', () => {
      const result = validateContentRequirements({
        content: 'hello',
        embeds: [],
        components: [],
      });
      expect(result).toBeUndefined();
    });

    it('returns undefined for classic message with embeds only', () => {
      const result = validateContentRequirements({
        content: '',
        embeds: [{ title: 'Test' }],
        components: [],
      });
      expect(result).toBeUndefined();
    });

    it('returns undefined for classic message with content + embeds + ActionRow', () => {
      const result = validateContentRequirements({
        content: 'hello',
        embeds: [{ title: 'Test' }],
        components: [makeActionRow()] as SupportedTopLevelComponent[],
      });
      expect(result).toBeUndefined();
    });

    it('returns undefined for V2 message with only V2 components (no content/embeds)', () => {
      const result = validateContentRequirements({
        content: '',
        embeds: [],
        components: [makeTextDisplay()],
      });
      expect(result).toBeUndefined();
    });

    it('returns undefined for V2 components + ActionRow + no content/embeds', () => {
      const result = validateContentRequirements({
        content: '',
        embeds: [],
        components: [makeActionRow(), makeTextDisplay()] as SupportedTopLevelComponent[],
      });
      expect(result).toBeUndefined();
    });
  });

  describe('invalid messages — mutual exclusivity violation', () => {
    it('returns error string when V2 components mixed with content', () => {
      const result = validateContentRequirements({
        content: 'hello',
        embeds: [],
        components: [makeTextDisplay()],
      });
      expect(typeof result).toBe('string');
      expect(result!.length).toBeGreaterThan(0);
    });

    it('returns error string when V2 components mixed with embeds', () => {
      const result = validateContentRequirements({
        content: '',
        embeds: [{ title: 'Test' }],
        components: [makeSection()],
      });
      expect(typeof result).toBe('string');
      expect(result!.length).toBeGreaterThan(0);
    });

    it('returns error string when V2 components mixed with both content and embeds', () => {
      const result = validateContentRequirements({
        content: 'hello',
        embeds: [{ title: 'Test' }],
        components: [makeContainer()] as SupportedTopLevelComponent[],
      });
      expect(typeof result).toBe('string');
    });
  });

  describe('invalid messages — empty message', () => {
    it('returns error string for empty message (no content, embeds, or components)', () => {
      const result = validateContentRequirements({
        content: '',
        embeds: [],
        components: [],
      });
      expect(typeof result).toBe('string');
      expect(result!.length).toBeGreaterThan(0);
    });

    it('returns error string for whitespace-only content and no embeds/components', () => {
      const result = validateContentRequirements({
        content: '   ',
        embeds: [],
        components: [],
      });
      expect(typeof result).toBe('string');
    });
  });

  describe('edge cases', () => {
    it('uses default empty arrays/strings when fields are undefined', () => {
      // validateContentRequirements has defaults: embeds=[], content='', components=[]
      const result = validateContentRequirements({});
      expect(typeof result).toBe('string'); // empty message error
    });

    it('legacy ActionRow + embeds is NOT a V2 violation', () => {
      const result = validateContentRequirements({
        content: '',
        embeds: [{ title: 'Test' }],
        components: [makeActionRow()] as SupportedTopLevelComponent[],
      });
      expect(result).toBeUndefined();
    });

    it('legacy ActionRow + content is NOT a V2 violation', () => {
      const result = validateContentRequirements({
        content: 'hello',
        embeds: [],
        components: [makeActionRow()] as SupportedTopLevelComponent[],
      });
      expect(result).toBeUndefined();
    });
  });
});

// ============================================================
// Tests: hasV2Components — additional type coverage
// ============================================================

describe('hasV2Components — individual V2 type coverage', () => {
  it('returns true for MediaGallery (type 12)', () => {
    expect(hasV2Components([makeMediaGallery()])).toBe(true);
  });

  it('returns true for File (type 13)', () => {
    expect(hasV2Components([makeFile()])).toBe(true);
  });

  it('returns true for Section (type 9)', () => {
    expect(hasV2Components([makeSection()])).toBe(true);
  });

  it('returns false for unknown component type', () => {
    expect(hasV2Components([{ type: 99 }])).toBe(false);
  });

  it('returns false for type 1 (ActionRow) alone', () => {
    expect(hasV2Components([{ type: 1 }])).toBe(false);
  });

  it('returns false for type 2 (Button) alone', () => {
    expect(hasV2Components([{ type: 2 }])).toBe(false);
  });
});

