import { describe, it, expect, vi } from 'vitest';
import type { z } from 'zod';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

import { validateMessage } from '~/utils/limits';
import { IS_COMPONENTS_V2_FLAG, V2_COMPONENT_TYPE_VALUES } from '~/constants';
import { switchToV2, switchToClassic } from '~/utils/messageMode';
import { topLevelComponentShape } from '~/server/api/utils/shapes';
import { data } from '~/utils/__tests__/helpers/messageData';

const V2_COPY = 'Components V2 messages cannot contain embeds or content.';
const EMPTY_COPY = 'Message must have content, embeds, or components.';

type Verdict = 'ok' | 'v2-exclusive' | 'empty' | 'other';

function verdict(result: string): Verdict {
  if (result === '') return 'ok';
  if (result === V2_COPY) return 'v2-exclusive';
  if (result === EMPTY_COPY) return 'empty';
  return 'other';
}

const textDisplay = () => ({ type: 10, content: 'Hello' });
const actionRow = () => ({ type: 1, components: [{ type: 2, style: 5, url: 'https://example.com', label: 'Click' }] });

const SET = IS_COMPONENTS_V2_FLAG;

interface Cell {
  id: string;
  why: string;
  input: Record<string, unknown>;
  expected: Verdict;
  changesAtM2: boolean;
}

const PARTITION: Cell[] = [
  // ---- flags bit UNSET (control half: verdicts must be identical across the residue-class change) ----
  {
    id: 'A1',
    why: 'structural-V2 disjunct is the sole carrier of hasV2; content is the sole carrier of hasContent',
    input: { components: [textDisplay()], content: 'Hi' },
    expected: 'v2-exclusive',
    changesAtM2: false,
  },
  {
    id: 'A2',
    why: 'embeds is the sole carrier of hasContent (content empty)',
    input: { components: [textDisplay()], embeds: [{ title: 'T' }] },
    expected: 'v2-exclusive',
    changesAtM2: false,
  },
  {
    id: 'A3',
    why: 'well-formed V2: components only. The 16 known bare-Text-Display records live here when unflagged',
    input: { components: [textDisplay()] },
    expected: 'ok',
    changesAtM2: false,
  },
  {
    id: 'A4',
    why: 'classic message with a legacy ActionRow and content — must stay sendable',
    input: { components: [actionRow()], content: 'Hi' },
    expected: 'ok',
    changesAtM2: false,
  },
  {
    id: 'A5',
    why: 'hasComponents is the sole carrier of the empty-message clause',
    input: { components: [actionRow()] },
    expected: 'ok',
    changesAtM2: false,
  },
  {
    id: 'A6',
    why: 'plain classic content, no components',
    input: { content: 'Hi' },
    expected: 'ok',
    changesAtM2: false,
  },
  {
    id: 'A7',
    why: 'genuinely empty message',
    input: {},
    expected: 'empty',
    changesAtM2: false,
  },

  // ---- flags bit SET (the residue class this partition is stated over) ----
  {
    id: 'B1',
    why: 'flag and structure agree on V2; content present',
    input: { flags: SET, components: [textDisplay()], content: 'Hi' },
    expected: 'v2-exclusive',
    changesAtM2: false,
  },
  {
    id: 'B2',
    why: 'POSITIVE CONTROL for the V2 class: bare Text Display, flag set — the 16 known records. '
      + 'Must remain sendable. A blanket "flag set => refuse" fix is killed by this cell.',
    input: { flags: SET, components: [textDisplay()] },
    expected: 'ok',
    changesAtM2: false,
  },
  {
    id: 'B3',
    why: 'RESIDUE: flag set, non-V2 components, content — decided as V2',
    input: { flags: SET, components: [actionRow()], content: 'Hi' },
    expected: 'v2-exclusive',
    changesAtM2: true,
  },
  {
    id: 'B4',
    why: 'flag set, non-V2 components, no content — verdict unchanged either way',
    input: { flags: SET, components: [actionRow()] },
    expected: 'ok',
    changesAtM2: false,
  },
  {
    id: 'B5',
    why: 'RESIDUE, and the shape of stored record 5712: flag set, no components, content. '
      + 'The flags disjunct is the SOLE carrier of hasV2 here — the mutant that drops it survives '
      + 'every other cell in this table and dies on this one.',
    input: { flags: SET, content: 'Hi' },
    expected: 'v2-exclusive',
    changesAtM2: true,
  },
  {
    id: 'B6',
    why: 'flag set on an otherwise empty message — the empty clause still decides',
    input: { flags: SET },
    expected: 'empty',
    changesAtM2: false,
  },
  {
    id: 'B7',
    why: 'RESIDUE: flag set, no components, embeds only — embeds is the sole carrier of hasContent '
      + 'within the flag-set half',
    input: { flags: SET, embeds: [{ title: 'T' }] },
    expected: 'v2-exclusive',
    changesAtM2: true,
  },
];

describe('send gate over the (flags-bit x structure x content-source) partition', () => {
  it.each(PARTITION)('$id — $why', ({ input, expected }) => {
    expect(verdict(validateMessage(data(input)))).toBe(expected);
  });

  it('the partition is complete over both halves of the flags bit', () => {
    expect(PARTITION.filter((c) => !('flags' in c.input))).toHaveLength(7);
    expect(PARTITION.filter((c) => 'flags' in c.input)).toHaveLength(7);
  });

  it('exactly three cells change verdict in the residue class; a fourth is a criterion failure', () => {
    expect(PARTITION.filter((c) => c.changesAtM2).map((c) => c.id)).toEqual(['B3', 'B5', 'B7']);
    // would violate this partition's residue-class scoping whatever the suite says.
    expect(PARTITION.filter((c) => c.changesAtM2).every((c) => 'flags' in c.input)).toBe(true);
  });
});

describe('sentinels — expectations sourced outside this codebase', () => {
  // Expected value: FALSE. Provenance: an owner-executed live send against Discord returned HTTP
  // 400, code 50035, MESSAGE_CANNOT_USE_LEGACY_FIELDS_WITH_COMPONENTS_V2, naming `content`.
  it('stored record 5712 is unsendable', () => {
    const record5712 = {
      flags: 32768,
      content: 'Complimenti {{user}} ! Sei il Member of The Month in ...',
      username: 'MOTM',
      avatar_url: 'https://example.com/a.png',
      components: [],
    } as unknown as MessageData;
    expect(validateMessage(record5712)).not.toBe('');
  });

  // Expected value: TRUE. Provenance: an owner-executed live send against Discord returned HTTP
  // 200 on exactly this shape. These are records that crash Statbot today; a correct `valid`
  // field marks them valid. If this ever goes red, the fix has been misread as addressing
  it('a bare top-level Text Display carrying the V2 flag is sendable', () => {
    const bareV2 = {
      flags: 32768,
      username: 'Statbot',
      components: [{ type: 10, content: 'Congratulations {{user}}' }],
    } as unknown as MessageData;
    expect(validateMessage(bareV2)).toBe('');
  });
});

describe('gate copy — asserted once, so the classifier above cannot silently degrade', () => {
  it('the mutual-exclusivity copy exists verbatim', () => {
    expect(validateMessage(data({ components: [textDisplay()], content: 'Hi' }))).toBe(V2_COPY);
  });
  it('the empty-message copy exists verbatim', () => {
    expect(validateMessage(data({}))).toBe(EMPTY_COPY);
  });
});

// The recovery round trip through mode-switching, at the data-effect layer.
//
// `handleModeSwitch` (src/components/DiscordMessageEditor/index.tsx) is a React callback that
// delegates to `switchToV2`/`switchToClassic` (~/utils/messageMode) for its data effects; these
// tests exercise those same functions directly.
//
// WHY IT MATTERS: an affected stored record loads in CLASSIC mode — `detectMode`
// never `flags`. So reaching the V2->classic branch requires toggling classic->V2 first. That
// outbound leg unconditionally clears content and embeds.

type Draft = { flags?: number; content?: string; embeds?: unknown[]; components?: { type: number }[] };

const STORED_5712: Draft = {
  flags: 32768,
  content: 'Complimenti {{user}} ! Sei il Member of The Month in ...',
  embeds: [],
  components: [],
};

describe('the generator is closed: V2->classic clears the flag over the whole class', () => {
  // Stated over the class of V2->classic switches, whatever the departing content, not over one
  // traced flow.
  const departingStates: [string, Draft][] = [
    ['V2 components present', { flags: 32768, components: [{ type: 10 }] }],
    ['V2 components plus a legacy ActionRow', { flags: 32768, components: [{ type: 10 }, { type: 1 }] }],
    ['no components, flag stranded', { flags: 32768, components: [] }],
    ['flag combined with an unrelated flag bit', { flags: 32768 | 4, components: [{ type: 10 }] }],
    ['no flags key at all', { components: [{ type: 10 }] }],
  ];

  it.each(departingStates)('%s -> no V2 flag afterwards', (_label, draft) => {
    const after = switchToClassic(draft as unknown as MessageData);
    expect((after.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(0);
  });

  it('clears only the V2 bit — unrelated flag bits survive', () => {
    const after = switchToClassic({ flags: 32768 | 4, components: [] } as unknown as MessageData);
    expect(after.flags).toBe(4);
  });

  it('the classic->V2 branch clears content and embeds but leaves an already-set flag alone', () => {
    const after = switchToV2({ flags: 32768, content: 'Hi', embeds: [{ title: 'T' }], components: [{ type: 1 }] } as unknown as MessageData);
    expect(after.content).toBe('');
    expect(after.embeds).toEqual([]);
    expect(after.components).toEqual([{ type: 1 }]);
    expect(after.flags).toBe(32768); // only switchToClassic touches the V2 flag
  });
});

describe('recovering a stored record through composer controls alone', () => {
  it('the record is unsendable as stored, and loads in CLASSIC mode', () => {
    expect(validateMessage({ ...STORED_5712, username: 'MOTM' } as unknown as MessageData)).not.toBe('');
    expect(STORED_5712.components).toEqual([]);
  });

  it('RECOVERY IS REACHABLE — but only via a round trip, and the outbound leg destroys the content', () => {
    const step1 = switchToV2(STORED_5712 as unknown as MessageData); // classic -> v2 (mandatory: the other leg is patched)
    expect(step1.content).toBe('');
    expect((step1.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);

    const step2 = switchToClassic(step1);            // v2 -> classic, clears the flag
    expect((step2.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(0);

    expect(validateMessage({ ...step2, username: 'MOTM' } as unknown as MessageData))
      .toBe('Message must have content, embeds, or components.');

    const step3 = { ...step2, content: STORED_5712.content };
    expect(validateMessage({ ...step3, username: 'MOTM' } as unknown as MessageData)).toBe('');
  });

  it('there is no shorter path: a save alone never clears the flag', () => {
    // the bit. Save-path normalisation that would clear it is out of scope for this repository.
    const savedAgain = { ...STORED_5712 };
    expect((savedAgain.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);
  });
});

// EXTENSIONS — additive cells covering an input class the original partition did not enumerate,
// raised by a question about the gate's behaviour and re-derived here by execution before being
// acted on.
//
//   - marked as extensions, so a reader can tell the original frozen set from the rest;

describe('EXT-1 — whitespace-only content: a class the original partition did not distinguish', () => {
  //
  // The open question is tracked outside this file so the population is measured before it gates.

  it('W1 — whitespace content + structurally-V2 components: gate PERMITS today', () => {
    expect(validateMessage(data({ content: '   ', components: [textDisplay()] }))).toBe('');
  });

  it('W2 — tabs and newlines behave identically to spaces', () => {
    expect(validateMessage(data({ content: '\n\t ', components: [textDisplay()] }))).toBe('');
  });

  it('W3 — whitespace content + flag set + no components: the EMPTY clause decides, not the V2 clause', () => {
    // Note this is unchanged by the residue-class change in both directions: hasContent is false
    // either way, so the mutual-exclusivity clause never fires. Whitespace is not a residue
    // question.
    expect(validateMessage(data({ content: '   ', flags: SET }))).toBe(EMPTY_COPY);
  });

