describe('EXT-2 — nested V2 under a non-V2 top level is NOT REPRESENTABLE', () => {
  // The gate, `hasV2Components`, and this file's predicate all detect V2-ness at TOP LEVEL ONLY.
  // That is sound — but by the shape of the real schema, exercised here rather than read as text:
  //   - the ONLY non-V2 top-level type accepted by `topLevelComponentShape` is the Action Row
  //     (type 1); every other member of the union is itself a V2 type;
