    draft: { flags: V2_FLAG, components: [CONTAINER] },
    d17Row: 'the flag over components within the schema and no content',
    expected: 'v2',
  },
  {
    id: 'bit=1 v2=1 classic=1',
    draft: { flags: V2_FLAG, content: 'hi', components: [CONTAINER] },
    d17Row: 'V2 components together with content or embeds',
    expected: 'choice',
