    '%s — the dialog announces a mode change IFF the disposition says the mode changes',
    (_id, cell) => {
      for (const [label, current, currentMode] of [
        ['over a Classic message', CURRENT_CLASSIC, 'classic'],
        ['over a V2 message', CURRENT_V2, 'v2'],
