import { isMessageValid } from '~/server/api/utils/messageValidity';
import { validateMessage } from '~/utils/limits';
import { data } from '~/utils/__tests__/helpers/messageData';

const textDisplay = () => ({ type: 10, content: 'Hello' });
const actionRow = () => ({ type: 1, components: [{ type: 2, style: 5, url: 'https://example.com', label: 'Click' }] });

describe('parity by construction', () => {
  it('agrees with the Send gate over representative payloads (flag-set bare V2, unflagged bare V2 permitting; flag residue refusing)', () => {
    // Expected values are the send-gate partition's own frozen verdicts for these exact payloads
    // (limits.send-gate-partition.test.ts cells B2, A3, B5) — an independent oracle, not this
    // predicate's own formula.
    const permitsBareV2 = data({ components: [textDisplay()], flags: 32768 });
    const permitsUnflaggedV2 = data({ components: [textDisplay()] });
    const refusesFlagResidue = data({ content: 'Hi', flags: 32768 });

    expect(isMessageValid(permitsBareV2)).toBe(true);
    expect(isMessageValid(permitsUnflaggedV2)).toBe(true);
    expect(isMessageValid(refusesFlagResidue)).toBe(false);
  });

  it('declares no validation logic of its own: agrees with the gate over a wider payload spread, not just the three cells above', () => {
    // Exercises the delegation directly rather than reading the module's text for a call count:
    // any clause `isMessageValid` added beyond the gate's own verdict would diverge from
    // `validateMessage` on one of these payloads and this assertion would catch it.
    const payloads = [
      data({ components: [textDisplay()], content: 'Hi' }),
      data({ components: [actionRow()], content: 'Hi' }),
      data({ components: [actionRow()] }),
      data({}),
      data({ embeds: [{ title: 'T' }] }),
      data({ flags: 32768 }),
      data({ flags: 32768, embeds: [{ title: 'T' }] }),
    ];
    for (const payload of payloads) {
      expect(isMessageValid(payload)).toBe(validateMessage(payload) === '');
    }
  });

  it('imports the gate directly, not via the `~/utils` barrel: the exported symbol is identical either way', async () => {
    // The import path itself (direct vs. barrel) has no runtime-observable difference — both
    // resolve to the same module singleton — so this asserts the one consequence that IS
    // observable: whichever path a caller uses, it reaches the same function object. The
    // import-path choice itself is a build-organization property with no behavioural equivalent;
    // see Outstanding Items.
    const barrel = await import('~/utils');
    const direct = await import('~/utils/limits');
    expect(barrel.validateMessage).toBe(direct.validateMessage);
  });
});

describe('sentinels — expectations sourced outside this codebase', () => {
  it('stored record 5712 computes false (owner-recorded Discord 400/50035)', () => {
    const record5712 = {
      flags: 32768,
      content: 'Complimenti {{user}} ! Sei il Member of The Month in ...',
      username: 'MOTM',
      avatar_url: 'https://example.com/a.png',
      components: [],
    } as unknown as MessageData;
    expect(isMessageValid(record5712)).toBe(false);
  });

  it('a bare top-level Text Display carrying the V2 flag computes true (owner-recorded HTTP 200)', () => {
    const bareV2 = {
      flags: 32768,
      username: 'Statbot',
      components: [{ type: 10, content: 'Congratulations {{user}}' }],
    } as unknown as MessageData;
    expect(isMessageValid(bareV2)).toBe(true);
  });
});

describe('known asymmetry: absent username', () => {
  it('a record with no username computes false, matching the gate (parity, not a defect)', () => {
    const noUsername = { content: 'Hi', embeds: [], components: [] } as unknown as MessageData;
    expect(isMessageValid(noUsername)).toBe(false);
  });

  it('control: the same record with a valid username computes true', () => {
    expect(isMessageValid(data({ content: 'Hi' }))).toBe(true);
  });
});

describe('the predicate is pure w.r.t. its argument', () => {
  it('does not mutate the record it evaluates', () => {
    const record = data({ content: 'Hi' });
    const before = JSON.parse(JSON.stringify(record));
    isMessageValid(record);
    expect(record).toEqual(before);
  });
});

describe('non-conformant stored data is not swallowed as true', () => {
  it('non-array embeds delegates to the gate ordinarily (no throw) and computes false', () => {
    // Unlike its two siblings below, this shape does not reach isMessageValid's catch clause —
    // validateMessage returns its ordinary empty-message copy. Kept as its own case (not merged
    // with the throwing siblings) precisely because it exercises a different branch.
    expect(isMessageValid(data({ embeds: {} }))).toBe(false);
  });
  it('non-string content computes false rather than throwing out', () => {
    expect(isMessageValid(data({ content: 5 }))).toBe(false);
  });
  it('null components computes false rather than throwing out', () => {
    expect(isMessageValid(data({ components: null }))).toBe(false);
  });
});

