import { validateMessage } from '~/utils/limits';
import {
  stripKeys, jsonModalSeed, resolveContentLoss, applyDisposition,
} from '~/utils';
import { discordMessageImportShape } from '~/server/api/utils/shapes';
import { IS_COMPONENTS_V2_FLAG } from '~/constants';
import useApiMethods from '~/providers/MessageProvider/useApiMethods';
import { switchToV2, switchToClassic } from '~/utils/messageMode';

type Draft = { flags?: number; content?: string; embeds?: unknown[]; components?: { type: number }[] };

describe('JSON-editor Load->save, executed end to end', () => {
  function loadAndSaveViaShippedProvider(stored: any, validated: unknown) {
    let state: any = stored;
    const messageRef: any = { current: state };
    const setMessage: any = (updater: any) => {
      state = typeof updater === 'function' ? updater(state) : updater;
      messageRef.current = state;
    };
    const upserted: any[] = [];
    const { updateMessage, saveMessage } = useApiMethods(
      messageRef,
      { current: false } as any,
      setMessage,
      async () => undefined,
      (opts: any) => { upserted.push(opts); },
    );
    updateMessage({ data: validated } as any);
    saveMessage();
    if (upserted.length !== 1) throw Error('save never reached the API layer');
    return upserted[0].message;
  }

  function editorRoundTrip(stored: any) {
    const displayed = jsonModalSeed(stored);
    const parsed = JSON.parse(displayed);
    const validated = discordMessageImportShape.parse(parsed) as any;
    const disposition = resolveContentLoss(
      validated.flags, validated.components, validated.content, validated.embeds,
    );
    if (disposition.requiresChoice) throw Error('fixture is row E — commitLoad would not load it');
    const next = applyDisposition(validated);
    return { displayed, disposition, saved: loadAndSaveViaShippedProvider(stored, next) };
  }

  const STORED_5712_FULL = {
    id: '5712',
    name: 'MOTM',
    data: {
      username: 'MOTM',
      flags: 32768,
      content: 'Complimenti {{user}} ! Sei il Member of The Month in ...',
      embeds: [],
      components: [],
    },
  };

  it('THE FALSITY SIGNATURE ITSELF — 5712 does NOT still carry flags 32768 after Load and save', () => {
    const { saved } = editorRoundTrip(STORED_5712_FULL);
    expect((saved.data.flags ?? 0) & IS_COMPONENTS_V2_FLAG).toBe(0);
  });

  it('and the repair is genuinely LOSSLESS for 5712 — the content survives', () => {
    const { saved } = editorRoundTrip(STORED_5712_FULL);
    expect(saved.data.content).toBe(STORED_5712_FULL.data.content);
    expect(validateMessage({ ...saved.data, username: 'MOTM' } as unknown as MessageData)).toBe('');
  });

  it('the flag DOES now reach the textarea (the silent strip is retired)', () => {
    const { displayed } = editorRoundTrip(STORED_5712_FULL);
    expect(JSON.parse(displayed).flags).toBe(IS_COMPONENTS_V2_FLAG);
  });

  it('...and the repair is what clears it: row D resolves to classic, and Load applies that', () => {
    const { disposition, saved } = editorRoundTrip(STORED_5712_FULL);
