const FLAG = 1 << 15;
const ACTION_ROW = { type: 1, components: [{ type: 2, style: 5, label: 'x', url: 'https://e.co' }] };

const rowDMembers: Array<[string, Record<string, unknown>]> = [
  ['content only (record 5712\'s own shape)', { content: 'hi', flags: FLAG }],
  ['embeds only', { embeds: [{ title: 't' }], flags: FLAG }],
  ['content AND embeds', { content: 'hi', embeds: [{ title: 't' }], flags: FLAG }],
  ['content + a non-V2 action row', { content: 'hi', flags: FLAG, components: [ACTION_ROW] }],
  ['embeds + a non-V2 action row', { embeds: [{ title: 't' }], flags: FLAG, components: [ACTION_ROW] }],
  ['whitespace-padded content', { content: '  hi  ', flags: FLAG }],
  ['flag OR-ed with other bits (SUPPRESS_EMBEDS)', { content: 'hi', flags: FLAG | 4 }],
  ['flag OR-ed with EPHEMERAL', { content: 'hi', flags: FLAG | 64 }],
];

// Every disposition-row-D member must resolve to something the floor accepts, or the fix
// silently drops content instead of loading it.
describe('row D disposition — applyDisposition(rowD) is accepted by the floor', () => {
  it.each(rowDMembers)('row D member — %s — resolves to something the floor accepts', (_label, draft) => {
    const disposition = resolveContentLoss(
      draft.flags as number | undefined,
      draft.components as undefined | { type: number }[],
      draft.content as string | undefined,
      draft.embeds as never,
    );
    expect(disposition.requiresChoice).toBe(false);

    const resolved = applyDisposition(draft as never);
    expect(validateContentRequirements(resolved as never)).toBeUndefined();
  });

  it('and the resolution is genuinely lossless for content (not merely floor-passing)', () => {
    const resolved = applyDisposition({ content: 'hi', flags: FLAG } as never);
    expect((resolved as { content?: string }).content).toBe('hi');
    expect(((resolved as { flags?: number }).flags ?? 0) & FLAG).toBe(0);
  });

  // Pins the property directly (bitwise AND against the flag), not a type assertion that
  // happens to pass on fixtures carrying no other bits — over the two rowDMembers entries that
  // DO carry another bit, so a regression that made applyDisposition drop other bits (not just
  // the V2 bit) would be caught here.
  it('the V2-bit clear preserves other flag bits (SUPPRESS_EMBEDS, EPHEMERAL)', () => {
    const withSuppressEmbeds = applyDisposition({ content: 'hi', flags: FLAG | 4 } as never);
    expect(((withSuppressEmbeds as { flags?: number }).flags ?? 0) & FLAG).toBe(0);
    expect(((withSuppressEmbeds as { flags?: number }).flags ?? 0) & 4).toBe(4);

    const withEphemeral = applyDisposition({ content: 'hi', flags: FLAG | 64 } as never);
    expect(((withEphemeral as { flags?: number }).flags ?? 0) & FLAG).toBe(0);
    expect(((withEphemeral as { flags?: number }).flags ?? 0) & 64).toBe(64);
  });
});

