describe('row D disposition — hole check: the fix opens no new hole', () => {
  const loadDisabled = (draft: Record<string, unknown> | null): boolean => {
    if (!draft) return true;
    return !!validateContentRequirements(applyDisposition(draft as never));
  };

  it('empty draft (no content/comps/flag) stays BLOCKED — floor Branch 2', () => {
    expect(loadDisabled({ flags: 0, content: '', embeds: [], components: [] })).toBe(true);
  });

  it('flag-only empty draft (row C — switchToV2 keeps it empty) stays BLOCKED', () => {
    const d = { flags: FLAG, content: '', embeds: [], components: [] };
    expect(resolveContentLoss(d.flags, d.components as never, d.content, d.embeds).row).toBe('C');
    expect(loadDisabled(d)).toBe(true);
  });

  it('whitespace-only content, no flag/comps stays BLOCKED (trim => empty)', () => {
    expect(loadDisabled({ flags: 0, content: '   ', embeds: [], components: [] })).toBe(true);
  });
});

// Record 5712, end to end, through the shipped seed -> parse -> resolve -> floor pipeline.
describe('row D disposition — record 5712 end to end', () => {
  const STORED_5712_FULL = {
    id: '5712',
    name: 'MOTM',
    data: {
      username: 'MOTM',
      flags: 32768,
      content: 'Complimenti {{user}} ! Sei il Member of The Month in ...',
      embeds: [],
      components: [],
    },
  };
  const seeded = () => JSON.parse(jsonModalSeed(STORED_5712_FULL as never));

  it('the repair now succeeds: resolved draft clears the floor', () => {
    const s = seeded();
    const resolved = applyDisposition(s);
    expect(validateContentRequirements(resolved)).toBeUndefined();
    expect(((resolved as { flags?: number }).flags ?? 0) & FLAG).toBe(0);
    expect((resolved as { content?: string }).content).toBe(s.content);
  });
});

