import { describe, it, expect, vi } from 'vitest';

vi.mock('~/env.mjs', () => ({
  env: {
    NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test',
  },
}));
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import { hashMessage, stripKeys, makeEditable } from '~/utils';
import { IS_COMPONENTS_V2_FLAG } from '~/constants';

const classicMessage = { name: 'Test', data: {} };

const v2Message = {
  name: 'Test',
  data: {
    flags: IS_COMPONENTS_V2_FLAG,
    components: [
      { type: 17, components: [{ type: 10, content: 'hi' }] },
    ],
  },
};

const v2MessageOtherComponent = {
  name: 'Test',
  data: {
    flags: IS_COMPONENTS_V2_FLAG,
    components: [
      { type: 17, components: [{ type: 10, content: 'a totally different body' }] },
    ],
  },
};

describe('hashMessage sees V2 (both directions)', () => {
  it('differs when a message gains V2 components a classic-only fixture never had', () => {
    expect(hashMessage(classicMessage)).not.toBe(hashMessage(v2Message));
  });

  it('differs when the V2 flag bit changes with everything else equal', () => {
    const withoutFlag = { name: 'Test', data: { components: v2Message.data.components } };
    const withFlag = { name: 'Test', data: { flags: IS_COMPONENTS_V2_FLAG, components: v2Message.data.components } };
    expect(hashMessage(withoutFlag)).not.toBe(hashMessage(withFlag));
  });

  it('differs when a component field changes (content inside a V2 container)', () => {
    expect(hashMessage(v2Message)).not.toBe(hashMessage(v2MessageOtherComponent));
  });

  it('is equal for the same data with keys in a different order', () => {
    const a = { name: 'Test', data: { flags: 0, content: 'hi', username: 'bot' } };
    const b = { name: 'Test', data: { username: 'bot', content: 'hi', flags: 0 } };
    expect(hashMessage(a)).toBe(hashMessage(b));
  });

  it('is equal for data differing only in embed/component `_key` values', () => {
    const withKeys = {
      name: 'Test',
      data: {
        components: [
          { _key: 'aaa', type: 17, components: [{ _key: 'bbb', type: 10, content: 'hi' }] },
        ],
      },
    };
    const withoutKeys = {
      name: 'Test',
      data: {
        components: [
          { type: 17, components: [{ type: 10, content: 'hi' }] },
        ],
      },
    };
    expect(hashMessage(withKeys)).toBe(hashMessage(withoutKeys));
  });
});

describe('the transport form round-trips the whole message', () => {
  it('stripKeys(makeEditable({data})).data carries components and flags (V2)', () => {
    const stored = {
      flags: IS_COMPONENTS_V2_FLAG,
      components: [
        { type: 17, components: [{ type: 10, content: 'hi' }] },
      ],
    };
    const editable = makeEditable({ data: stored });
    const roundTripped = stripKeys({ data: editable.data }).data;
    expect(roundTripped.flags).toBe(IS_COMPONENTS_V2_FLAG);
    expect(roundTripped.components).toEqual(stored.components);
    expect(roundTripped.content).toBeUndefined();
    expect(roundTripped.embeds).toBeUndefined();
  });

  it('stripKeys(makeEditable({data})).data carries classic content + username unchanged', () => {
    const stored = {
      content: 'hello world', username: 'Bot', avatar_url: 'https://example.com/a.png',
    };
    const editable = makeEditable({ data: stored });
    const roundTripped = stripKeys({ data: editable.data }).data;
    expect(roundTripped).toEqual(stored);
  });
});

import equal from 'fast-deep-equal';
import { mergeProps } from 'react-aria';

import getCDNUrl from './getCDNUrl';

