import TextIcon from '~/assets/svg/TextIcon';
import VoiceIcon from '~/assets/svg/VoiceIcon';
import {
  DEFAULT_IMAGE_URL, DISCORD_CDN_BASE, IS_COMPONENTS_V2_FLAG,
  TEXT_CHANNEL_TYPES, V2_COMPONENT_TYPE_VALUES,
} from '~/constants';
import { applyModeSwitch, isMessageV2 } from '~/utils/messageMode';

export { default as formatMutationError } from './formatMutationError';
export { default as isValidUrl } from './isValidUrl';
export * from './limits';
export { default as omit } from './omit';
export { default as pushSorted } from './pushSorted';
export * from './typeguards';

export const V2_COMPONENT_TYPES = new Set<number>(V2_COMPONENT_TYPE_VALUES);

export function hasV2Components(
  components: undefined | { type: number }[],
): boolean {
  if (!components || !Array.isArray(components)) return false;
  return components.some((c) => V2_COMPONENT_TYPES.has(c.type));
}

export function hasClassicContent(
  data: { content?: string, embeds?: unknown[] },
): boolean {
  if (data.content?.trim()) return true;
  if (data.embeds && data.embeds.length > 0) {
    return data.embeds.some((embed) => {
      if (!embed || typeof embed !== 'object') return false;
      return Object.entries(embed).some(
        ([key, val]) => key !== '_key' && val !== undefined && val !== '' && val !== null
          && !(Array.isArray(val) && val.length === 0),
      );
    });
  }
  return false;
}

export function hasV2Content(
  components: undefined | { type: number }[],
): boolean {
  return hasV2Components(components);
}

/**
 * Enforce mutual exclusivity for imported/pasted JSON data.
 * If V2 components detected, strip content/embeds. Otherwise strip V2 components.
 * Mode detection runs on the raw data BEFORE any schema filtering.
 */
export function enforceImportMutualExclusivity<
  T extends { content?: string, embeds?: unknown[], components?: { type: number }[] },
>(data: T): { data: T, detectedMode: MessageMode } {
  const isV2 = hasV2Components(data.components);
  const cleaned = { ...data };
  if (isV2) {
    delete cleaned.content;
    delete cleaned.embeds;
  } else if (Array.isArray(cleaned.components)) {
    cleaned.components = cleaned.components.filter(
      (c) => !V2_COMPONENT_TYPES.has(c.type),
    ) as T['components'];
  }
  return { data: cleaned, detectedMode: isV2 ? 'v2' : 'classic' };
}

export interface ContentLossOption {
  mode: MessageMode;
  dropSet: readonly string[];
}

export interface ContentLossChoice {
  row: 'E';
  mode: null;
  noticeClass: 'choice';
  requiresChoice: true;
  options: readonly ContentLossOption[];
}

export interface ContentLossSettled {
  row: 'A' | 'B' | 'C' | 'D';
  mode: MessageMode;
  noticeClass: 'none' | 'warn-v2-flag-added' | 'warn-v2-flag-conflict';
  requiresChoice: false;
  options: null;
}

export type ContentLossDisposition = ContentLossChoice | ContentLossSettled;
export type ContentLossRow = ContentLossDisposition['row'];
export type ContentLossNoticeClass = ContentLossDisposition['noticeClass'];

interface RowEDraftLike {
  flags: number | undefined;
  components: undefined | { type: number }[];
  content: undefined | string;
  embeds: undefined | unknown[];
}

function diffDroppedKeys(before: RowEDraftLike, after: RowEDraftLike): string[] {
  const dropped: string[] = [];
  if (JSON.stringify(before.components ?? []) !== JSON.stringify(after.components ?? [])) {
    dropped.push('components');
  }
  if ((before.content ?? '') !== (after.content ?? '')) {
    dropped.push('content');
  }
  if (JSON.stringify(before.embeds ?? []) !== JSON.stringify(after.embeds ?? [])) {
    dropped.push('embeds');
  }
  return dropped;
}

function rowEOptions(draft: RowEDraftLike): readonly ContentLossOption[] {
  const asModeSwitchDraft = draft as unknown as
    Pick<Partial<MessageData>, 'content' | 'embeds' | 'components' | 'flags'>;
  return (['classic', 'v2'] as const).map((mode) => ({
    mode,
    dropSet: diffDroppedKeys(
      draft,
      applyModeSwitch(mode, asModeSwitchDraft) as unknown as RowEDraftLike,
    ),
  }));
}

export function resolveContentLoss(
  flags: number | undefined,
  components: undefined | { type: number }[],
  content: undefined | string,
  embeds: undefined | unknown[],
): ContentLossDisposition {
  const flagBit = !!((flags ?? 0) & IS_COMPONENTS_V2_FLAG);
  const hasComponents = hasV2Components(components);
  const hasContent = hasClassicContent({ content, embeds });

  if (hasComponents && hasContent) {
    return {
      row: 'E',
      mode: null,
      noticeClass: 'choice',
      requiresChoice: true,
      options: rowEOptions({
        flags, components, content, embeds,
      }),
    };
  }
  if (!hasComponents && !hasContent) {
    return {
      row: flagBit ? 'C' : 'A',
      mode: flagBit ? 'v2' : 'classic',
      noticeClass: 'none',
      requiresChoice: false,
      options: null,
    };
  }
  if (hasComponents) {
    return {
      row: flagBit ? 'C' : 'B',
      mode: 'v2',
      noticeClass: flagBit ? 'none' : 'warn-v2-flag-added',
      requiresChoice: false,
      options: null,
    };
  }
  return {
    row: flagBit ? 'D' : 'A',
    mode: 'classic',
    noticeClass: flagBit ? 'warn-v2-flag-conflict' : 'none',
    requiresChoice: false,
    options: null,
  };
}

export function gateBeforePersist(
  draft: Pick<Partial<MessageData>, 'flags' | 'components' | 'content' | 'embeds'>,
): { mustAsk: boolean, options: readonly ContentLossOption[] | null } {
  const disposition = resolveContentLoss(
    draft.flags as number | undefined,
    draft.components as undefined | { type: number }[],
    draft.content,
    draft.embeds,
  );
  return { mustAsk: disposition.requiresChoice, options: disposition.options };
}

export function applyDisposition<
  T extends Pick<Partial<MessageData>, 'content' | 'embeds' | 'components' | 'flags'>,
>(
  draft: T,
  chosenMode?: MessageMode,
): T {
  const disposition = resolveContentLoss(
    draft.flags as number | undefined,
    draft.components as undefined | { type: number }[],
    draft.content,
    draft.embeds,
  );
  if (disposition.requiresChoice) {
    if (!chosenMode) {
      throw new Error('applyDisposition: a chosenMode is required when requiresChoice is true');
    }
    return applyModeSwitch(chosenMode, draft);
  }
  return applyModeSwitch(disposition.mode, draft);
}

export function noticeMessageForSettled(disposition: ContentLossSettled): string | null {
  switch (disposition.noticeClass) {
    case 'warn-v2-flag-added':
      return 'This message has Components V2 content but the Components V2 flag was not set — it has been set to match.';
    case 'warn-v2-flag-conflict':
      return 'This message has the Components V2 flag but also has content or embeds, which cannot be combined — it has been saved as Classic and the flag cleared.';
    case 'none':
    default:
      return null;
  }
}

function joinWithAnd(items: readonly string[]): string {
  return items.length === 1
    ? items[0]
    : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

const DROP_SET_LABELS: Record<string, string> = {
  components: 'your Components V2 components',
  content: 'your message content',
  embeds: 'your embeds',
};

export function describeDropSet(dropSet: readonly string[]): string {
  if (dropSet.length === 0) return 'Nothing will be lost.';
  return `This will drop ${joinWithAnd(dropSet.map((key) => DROP_SET_LABELS[key] ?? key))}.`;
}
export interface LoadDiff {
  modeChanges: boolean;
  fromMode: MessageMode;
  toMode: MessageMode;
}

function settledMode(draft: Pick<Partial<MessageData>, 'flags' | 'components' | 'content' | 'embeds'>): MessageMode {
  const disposition = resolveContentLoss(
    draft.flags as number | undefined,
    draft.components as undefined | { type: number }[],
    draft.content,
    draft.embeds,
  );
  return disposition.requiresChoice ? (isMessageV2(draft) ? 'v2' : 'classic') : disposition.mode;
}

export function computeLoadDiff(
  current: Pick<Partial<MessageData>, 'flags' | 'components' | 'content' | 'embeds'>,
  incoming: Pick<Partial<MessageData>, 'flags' | 'components' | 'content' | 'embeds'>,
): LoadDiff {
  const fromMode: MessageMode = settledMode(current);
  const toMode: MessageMode = settledMode(incoming);
  return {
    modeChanges: fromMode !== toMode, fromMode, toMode,
  };
}

const MODE_LABELS: Record<MessageMode, string> = {
  classic: 'Classic',
  v2: 'Components V2',
};

export function describeLoadDiff(diff: LoadDiff): string {
  const parts: string[] = [];
  if (diff.modeChanges) parts.push(`switch from ${MODE_LABELS[diff.fromMode]} to ${MODE_LABELS[diff.toMode]}`);
  const overwrite = 'This will overwrite the current message.';
  if (!parts.length) return overwrite;
  return `${overwrite} It will ${parts.join('; ')}.`;
}

export { default as voided } from './voided';
export const extractWebhookDiscordId = (url: string) => {
  const match = url.match(/(?<=\/webhooks\/)\d+(?=\/)/);
  return match ? match[0] : undefined;
};

export const setCallback = <T>(set: Dispatch<SetStateAction<T>>, cb: T) => {
  set(() => cb);
};

export function createSyntheticClickEvent(e: PressEvent): MouseEvent {
  return {
    ...e, currentTarget: e.target, preventDefault: () => {},
  } as unknown as MouseEvent;
}

export function genUuid(length = 16) {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * length | 0;
    const v = c === 'x' ? r : ((r & 0x3) | 0x8);
    return v.toString(length);
  });
}

export function withTouchEndFix<E extends Element, T extends HTMLAttributes<E>>(attributes: T): T {
  return mergeProps(attributes, {
    // https://github.com/facebook/react/issues/9809#issuecomment-395607117
    onTouchEnd: (e: TouchEvent) => {
      e.preventDefault();
      e.stopPropagation();
    },
  }) as T;
}

interface Rect {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

interface EventPoint {
  clientX: number;
  clientY: number;
  width?: number;
  height?: number;
  radiusX?: number;
  radiusY?: number;
}

function getPointClientRect(point: EventPoint): Rect {
  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing, @typescript-eslint/no-non-null-assertion
  const offsetX = (point.width! / 2) || point.radiusX || 0;
  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing, @typescript-eslint/no-non-null-assertion
  const offsetY = (point.height! / 2) || point.radiusY || 0;

  return {
    top: point.clientY - offsetY,
    right: point.clientX + offsetX,
    bottom: point.clientY + offsetY,
    left: point.clientX - offsetX,
  };
}

function areRectanglesOverlapping(a: Rect, b: Rect) {
  // check if they cannot overlap on x axis
  if (a.left > b.right || b.left > a.right) {
    return false;
  }
  // check if they cannot overlap on y axis
  if (a.top > b.bottom || b.top > a.bottom) {
    return false;
  }
  return true;
}

export function withNearPressFix<E extends Element, T extends HTMLAttributes<E>>(
  props: PressProps,
  attributes: T,
): T {
  return mergeProps(attributes, {
    onPointerUp: ((e: PointerEvent) => {
      const rect = (e.currentTarget as Element).getBoundingClientRect();
      const pointRect = getPointClientRect(e);
      const isOverTarget = areRectanglesOverlapping(rect, pointRect);
      if (!isOverTarget) {
        props.onPressEnd?.({
          type: 'pressend',
          pointerType: 'touch',
          target: e.currentTarget as Element,
          shiftKey: e.shiftKey,
          metaKey: e.metaKey,
          ctrlKey: e.ctrlKey,
          altKey: e.altKey,
          x: e.clientX,
          y: e.clientY,
          continuePropagation: () => {},
        });

        props.onPress?.({
          type: 'press',
          pointerType: 'touch',
          target: e.currentTarget as Element,
          shiftKey: e.shiftKey,
          metaKey: e.metaKey,
          ctrlKey: e.ctrlKey,
          altKey: e.altKey,
          x: e.clientX,
          y: e.clientY,
          continuePropagation: () => {},
        });
      }
    }),
  }) as T;
}

export function extractKeys<T, K extends keyof T>(obj: T, keys: K[]): [Pick<T, K>, Omit<T, K>] {
  const picked: Pick<T, K> = {} as Pick<T, K>;
  const omitted: Omit<T, K> = {} as Omit<T, K>;
  for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
    if (keys.includes(key as K)) picked[key as K] = value as T[K];
    else omitted[key as keyof Omit<T, K>] = value as Omit<T, K>[keyof Omit<T, K>];
  }
  return [picked, omitted];
}

export function mergeEventListeners<T>(...listeners: (undefined | ((e: T) => void))[]) {
  return (e: T) => {
    listeners.forEach((listener) => {
      if (listener) listener(e);
    });
  };
}

export function shallowEqual<T extends Record<string, unknown>>(old: T, current: T) {
  const oldKeys = Object.keys(old);
  const currentKeys = Object.keys(current);
  if (oldKeys.length !== currentKeys.length) return false;

  for (const [key, value] of Object.entries(old)) {
    if (current[key] !== value) return false;
  }

  for (const key of currentKeys) {
    if (!Object.prototype.hasOwnProperty.call(old, key)) return false;
  }

  return true;
}

export function typedDeepEqual<T>(a: T, b: T) {
  return equal(a, b);
}

export function extractDataProps(props: unknown) {
  const dataProps: Record<string, unknown> = {};
  Object.keys(props as Record<string, unknown>).forEach((key) => {
    if (key.startsWith('data-')) dataProps[key] = (props as Record<string, unknown>)[key];
  });
  return dataProps;
}

