export function makeEditable<T extends Partial<ActiveMessage> | Partial<ApiMessage>>(
  message: T,
): ActiveMessage {
  const casted = JSON.parse(JSON.stringify(message)) as ActiveMessage;
  for (const embed of casted.data.embeds ?? []) {
    if (!embed._key) embed._key = genUuid();
    for (const field of embed.fields ?? []) {
      if (!field._key) field._key = genUuid();
    }
  }
  if (casted.data.components) {
    casted.data.components = casted.data.components.map(injectComponentKeys);
  }

  return casted;
}

export function injectComponentKeys(component: Record<string, unknown>): EditableTopLevelComponent {
  const c = { ...component };
  if (!c._key) c._key = genUuid();

  // Action row → inject keys into child buttons
  if (c.type === 1 && Array.isArray(c.components)) {
    c.components = (c.components as Record<string, unknown>[]).map((child) => {
      if (!child._key) child._key = genUuid();
      return child;
    });
  }

  // Section → inject keys into text display children + accessory
  if (c.type === 9) {
    if (Array.isArray(c.components)) {
      c.components = (c.components as Record<string, unknown>[]).map((child) => {
        if (!child._key) child._key = genUuid();
        return child;
      });
    }
    if (c.accessory && typeof c.accessory === 'object') {
      const acc = { ...(c.accessory as Record<string, unknown>) };
      if (!acc._key) acc._key = genUuid();
      c.accessory = acc;
    }
  }

  // Media gallery → inject keys into items
  if (c.type === 12 && Array.isArray(c.items)) {
    c.items = (c.items as Record<string, unknown>[]).map((item) => {
      if (!item._key) item._key = genUuid();
      return item;
    });
  }

  // Container → recurse into children
  if (c.type === 17 && Array.isArray(c.components)) {
    c.components = (c.components as Record<string, unknown>[]).map(injectComponentKeys);
  }

  return c as unknown as EditableTopLevelComponent;
}

/** Deep-clones a component and regenerates all `_key` values recursively. */
export function rekeyComponent(c: EditableTopLevelComponent): EditableTopLevelComponent {
  const stripped = stripComponentKeys(
    JSON.parse(JSON.stringify(c)) as Record<string, unknown>,
  );
  return injectComponentKeys(stripped);
}

function stripComponentKeys(
  component: Record<string, unknown>,
): Record<string, unknown> {
  const c = { ...component };
  delete c._key;

  if (c.type === 1 && Array.isArray(c.components)) {
    c.components = (c.components as Record<string, unknown>[]).map(stripComponentKeys);
  }

  if (c.type === 9) {
    if (Array.isArray(c.components)) {
      c.components = (c.components as Record<string, unknown>[]).map(stripComponentKeys);
    }
    if (c.accessory && typeof c.accessory === 'object') {
      const { _key: _, ...rest } = c.accessory as Record<string, unknown>;
      c.accessory = rest;
    }
  }

  if (c.type === 12 && Array.isArray(c.items)) {
    c.items = (c.items as Record<string, unknown>[]).map((item) => {
      const { _key: _, ...rest } = item as Record<string, unknown>;
      return rest;
    });
  }

  if (c.type === 17 && Array.isArray(c.components)) {
    c.components = (c.components as Record<string, unknown>[]).map(stripComponentKeys);
  }

  return c;
}

export function stripKeys<T extends { data?: EditableMessageData }>(message: T) {
  const casted = JSON.parse(JSON.stringify(message));
  for (const embed of casted.data?.embeds ?? []) {
    delete embed._key;
    for (const field of embed.fields ?? []) {
      delete field._key;
    }
  }
  if (Array.isArray(casted.data?.components)) {
    casted.data.components = (casted.data.components as Record<string, unknown>[])
      .map(stripComponentKeys);

    const hasV2 = (casted.data.components as { type: number }[]).some(
      (c) => V2_COMPONENT_TYPES.has(c.type),
    );
    if (hasV2) {
      casted.data.flags = ((casted.data.flags as number) || 0) | IS_COMPONENTS_V2_FLAG;
    }
  }

  return casted as ApiMessage;
}

export function saveAsPayload(message: Pick<ActiveMessage, 'data'>): MessageData {
  return stripKeys(message).data;
}

export function jsonModalSeed(message: null | undefined | ActiveMessage): string {
  return JSON.stringify(stripKeys(message ?? {}).data, null, 2);
}

const DISCORD_EPOCH = 1420070400000;
export function timestampFromSnowflake(snowflake: string): number {
  const bits = BigInt(snowflake).toString(2).padStart(64, '0');
  return parseInt(bits.substring(0, 42), 2) + DISCORD_EPOCH;
}
